// Generated by AI
using System.Collections.Generic;
using TMPro;
using UnityEngine;

public class HUDController : MonoBehaviour
{
    [SerializeField] private TMP_Text missionText; // Text that shows the current mission
    [SerializeField] private TMP_Text inventoryText; // Text that lists the collected items
    [SerializeField] private string emptyInventoryLabel = "Empty"; // Text shown when there are no items
    [SerializeField] private GameObject factPanel; // Panel for the "Did you know...?" window
    [SerializeField] private TMP_Text factTitleText; // Title of the historical fact
    [SerializeField] private TMP_Text factBodyText; // Body of the historical fact

    private readonly List<string> items = new List<string>(); // Names of the collected items

    // Sets the starting state of the HUD
    private void Start()
    {
        RefreshInventory();

        if (factPanel != null)
        {
            factPanel.SetActive(false);
        }
    }

    // Closes the fact window when the player presses Enter (there is no timer)
    private void Update()
    {
        if (factPanel != null && factPanel.activeSelf &&
            (Input.GetKeyDown(KeyCode.Return) || Input.GetKeyDown(KeyCode.KeypadEnter)))
        {
            CloseFact();
        }
    }

    // Updates the text of the current mission
    public void SetMission(string mission)
    {
        if (missionText != null)
        {
            missionText.text = mission;
        }
    }

    // Adds an item to the inventory if it is not already there
    public void AddItem(string itemName)
    {
        if (string.IsNullOrEmpty(itemName) || items.Contains(itemName))
        {
            return;
        }

        items.Add(itemName);
        RefreshInventory();
    }

    // Removes an item from the inventory
    public void RemoveItem(string itemName)
    {
        if (items.Remove(itemName))
        {
            RefreshInventory();
        }
    }

    // Rebuilds the inventory text, one item per line
    private void RefreshInventory()
    {
        if (inventoryText == null)
        {
            return;
        }

        inventoryText.text = items.Count == 0 ? emptyInventoryLabel : string.Join("\n", items);
    }

    // Opens the "Did you know...?" window and keeps it open until the player closes it
    public void ShowFact(string title, string body)
    {
        if (factPanel == null)
        {
            return;
        }

        if (factTitleText != null)
        {
            factTitleText.text = title;
        }

        if (factBodyText != null)
        {
            factBodyText.text = body;
        }

        factPanel.SetActive(true);
    }

    // Closes the "Did you know...?" window (also used by the close button)
    public void CloseFact()
    {
        if (factPanel != null)
        {
            factPanel.SetActive(false);
        }
    }
}